def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    extreme_count = 0
    urgent_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= 120:
                    extreme_count += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22
    critical_self = hp <= 2 or no_water_days >= 2
    pressured_self = hp <= 4 or no_water_days >= 1

    if critical_self:
        if extreme_count >= 2:
            bid = 118.0 if budget >= 118.0 else budget
        else:
            bid = max(78.0, min(110.0, max_prev + 3.0))
    elif pressured_self:
        if extreme_count >= 2:
            bid = 32.0 if supply_loose else 48.0
        else:
            base = max(42.0, avg_prev + 2.0)
            if supply_tight:
                base += 10.0
            bid = min(85.0, base)
    else:
        if extreme_count >= 2:
            bid = 12.0 if supply_loose else 22.0
        else:
            base = 24.0
            if max_prev > 0:
                base = max(24.0, min(60.0, avg_prev * 0.75 + 3.0))
            if supply_tight:
                base += 8.0
            elif supply_loose:
                base -= 6.0
            bid = base

    if urgent_opp_count >= 2 and not critical_self:
        bid *= 0.85

    if day >= 8:
        if pressured_self:
            bid += 8.0
        else:
            bid += 3.0

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    affordable = max(0.0, budget - reserve_floor)
    if critical_self:
        affordable = budget

    bid = min(budget, bid)
    if affordable > 0:
        bid = min(bid, affordable) if not critical_self else min(bid, budget)
    else:
        bid = min(bid, budget)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Estimate opponent pressure from yesterday's bids (immediate reaction only)
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base bid target: when others bid high, we must match to avoid being outbid on survival days.
    # Use supply to slightly adjust: higher supply can tolerate slightly lower bids.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # If others were bidding near/above ~1.55*salary, they likely had enough to survive; match a fraction.
    # If highest was low (~0.4*salary), survival may require still being competitive; bid moderate-high.
    low_threshold = DAILY_SALARY * 0.45
    high_threshold = DAILY_SALARY * 1.55

    if highest_prev_bid >= high_threshold:
        target = DAILY_SALARY * (1.35 - 0.25 * supply_norm)
    elif highest_prev_bid >= low_threshold:
        target = max(DAILY_SALARY * 0.95, highest_prev_bid * 0.85)
        target = target * (0.98 - 0.08 * supply_norm)
    else:
        # Opponents likely underbidding like Alex/David; still bid enough to secure water for ourselves.
        target = DAILY_SALARY * (1.05 - 0.15 * supply_norm)

    # HP-aware adjustment: if we're low HP, bid more to prevent death.
    hp = float(my_status['hp'])
    no_water_days = int(my_status.get('no_water_days', 0) or 0)

    if hp <= 1.5:
        target *= 1.15
    elif hp <= 3.0:
        target *= 1.05
    elif no_water_days >= 2:
        target *= 1.10

    # Budget cap and safety floor: never exceed budget; also avoid bidding too low if budget allows.
    budget = float(my_status['budget'])
    if budget <= 0.0:
        return 0.0

    # If we can afford it, bid at least enough to be competitive; otherwise bid a fraction.
    min_competitive = DAILY_SALARY * 0.85
    if budget >= min_competitive:
        bid = min(budget, max(target, min_competitive))
    else:
        bid = min(budget, max(target, budget * 0.6))

    # Final clamp
    bid = max(0.0, min(bid, budget))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no active opponents, bid a minimal amount to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Default bid if no previous bids are available (e.g., Day 1 or all opponents new)
    if not yesterday_bids:
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        return min(my_status['budget'], DAILY_SALARY * 0.55)

    highest_prev_bid = max(yesterday_bids)

    # Adjust bid based on opponent's previous aggression and my health
    if highest_prev_bid >= DAILY_SALARY * 0.85: # Opponent was very aggressive
        if my_status['hp'] > 3: # I am relatively healthy, can afford to be conservative
            bid = DAILY_SALARY * 0.3
        else: # I am not healthy, must bid aggressively to survive
            bid = DAILY_SALARY * 0.95
    else: # Opponent was not overly aggressive, try to win efficiently
        # Bid slightly above their highest previous bid, but no less than a base amount
        bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

    # Ensure bid doesn't exceed current budget
    return min(my_status['budget'], bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    alive = [o for o in opponents_status.values() if o['alive']]
    if not alive:
        return min(budget, SALARY * 0.3)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        # First day or no data: be conservative
        base = SALARY * 0.4
        if hp <= 3:
            base = SALARY * 0.55
    else:
        max_prev = max(yesterday_bids)
        # If someone very aggressive, we may need to match or avoid
        if max_prev >= SALARY * 1.0:
            # Aggressive environment: bid high only if necessary
            if hp <= 2:
                base = SALARY * 0.9
            else:
                base = SALARY * 0.5
        else:
            # Moderate: outbid the median by a small amount
            sorted_bids = sorted(yesterday_bids)
            median = sorted_bids[len(yesterday_bids)//2]
            base = max(SALARY * 0.4, median + 1.5)
            if hp <= 2:
                base = max(base, SALARY * 0.7)

    # Ensure bid is within budget and not more than salary
    bid = min(budget, base)
    # Also cap at 0.9*salary to preserve some budget for future
    bid = min(bid, SALARY * 0.9)
    return float(bid)
